   809→    private void failBatch(
   810→        ProducerBatch batch,
   811→        RuntimeException topLevelException,
   812→        boolean adjustSequenceNumbers
   813→    ) {
   814→        failBatch(batch, topLevelException, batchIndex -> topLevelException, adjustSequenceNumbers);
