   853→    /**
   854→     * Transfer the record batches into a list of produce requests on a per-node basis
   855→     */
   856→    private void sendProduceRequests(Map<Integer, List<ProducerBatch>> collated, long now) {
   857→        for (Map.Entry<Integer, List<ProducerBatch>> entry : collated.entrySet())
   858→            sendProduceRequest(now, entry.getKey(), acks, requestTimeoutMs, entry.getValue());
